"""Veridex updater. Put this file in the veridex folder (next to README.md) and run:  python update_11.py"""
import base64, os
HERE = os.path.dirname(os.path.abspath(__file__))
FILES = {'db.py': '', 'core/sitecheck.py': '', 'core/checker.py': '', 'zeus/engine.py': '', 'api/main.py': '', 'bot/telegram_bot.py': '', 'landing/dashboard.html': '', 'landing/ananse.html': '', 'tools/reset_db.py': ''}
for rel, b in FILES.items():
    p = os.path.join(HERE, *rel.split("/"))
    os.makedirs(os.path.dirname(p), exist_ok=True)
    open(p, "wb").write(base64.b64decode(b))
    print("updated", rel)
print("Done. Now run: pip install -r requirements.txt   then restart the bot.")
